<script lang="js">
import { defineComponent, onMounted, reactive, ref, watch } from "vue";
import { api } from "boot/axios"
import { useQuasar } from "quasar"
const recordActive = ref("deposit");
const searchForm = reactive({
  turnover: {
    startDate: "",
    endDate: "",
    current: 1
  },
  rebates: {
    startDate: "",
    endDate: "",
    current: 1
  },
  transfer: {
    startDate: "",
    endDate: "",
    current: 1
  },
  withdraw: {
    startDate: "",
    endDate: "",
    current: 1
  },
  deposit: {
    startDate: "",
    endDate: "",
    current: 1
  }
});
const dataState = reactive({
  deposit: [],
  rebates: [],
  transfer: [],
  withdraw: [],
  turnover: []
});
const commonColumns = [
  {
    label: "Serial Number",
    field: "serialNumber"
  }
];
const tableColumns = {
  deposit: [
    ...commonColumns,
    {
      label: "ยอดเงิน",
      field: "depositAmount"
    },
    {
      label: "สถานะ",
      field: "status"
    },
    {
      label: "วันที่ฝาก",
      field: "depositDate",
      // slots: { customRender: "depositDate" }
    }
  ],
  withdraw: [
    ...commonColumns,
    {
      label: "ยอดเงิน",
      field: "withdrawAmount"
    },
    {
      label: "สถานะ",
      field: "status"
    },
    {
      label: "วันที่ถอน",
      field: "withdrawDate",
      // slots: { customRender: "withdrawDate" }
    }
  ],
  transfer: [
    ...commonColumns,
    {
      label: "รายละเอียดการโอน",
      field: "type",
      key: "type",
      // slots: { customRender: "type" }
    },
    {
      label: "ยอดเงิน",
      field: "amount",
      key: "withdrawAmount"
    },
    {
      label: "สถานะ",
      field: "status",
      key: "status",
      // slots: { customRender: "status" }
    },
    {
      label: "เวลาโอน",
      field: "transferDate",
      key: "transferDate",
      // slots: { customRender: "transferDate" }
    }
  ],
  rebates: [
    ...commonColumns,
    {
      label: "ชื่อผู้มีสิทธิ์สูง",
      field: "privilegeName"
    },
    {
      label: "ยอดเงิน",
      field: "amount"
    },
    {
      label: "เวลาบันทึก",
      field: "recordTime",
      // slots: { customRender: "recordTime" }
    }
  ],
  turnover: [
    ...commonColumns,
    {
      label: "รูปแบบ",
      field: "type"
    },
    {
      label: "ยอดเงิน",
      field: "amount"
    },
    {
      label: "รูปแบบ",
      field: "subType"
    },
    {
      label: "เวลาบันทึก",
      field: "recordTime",
      // slots: { customRender: "recordTime" }
    }
  ]
};
const loading = ref(false);
const pagination = reactive({
  pageSize: 10,
  total: 0
});

export default defineComponent({
  name: "TransitRecordView",
  setup() {
    watch(recordActive, (currentValue, oldValue) => {
      searchRecord()
    });
    const $q = useQuasar()

    const recordUrl = {
      deposit: "/session/member/deposit",
      transfer: "/session/member/transfer",
      turnover: "/session/member/moneyChange",
      withdraw: "/session/member/withdraw",
      rebates: "/session/member/privilege",
    };

    const searchRecord = () => {
      loading.value = true;
      api.get(recordUrl[recordActive.value], {
        params: searchForm[recordActive.value]
      }).then((ret) => {
        const response = ret.data
          const dataSource = dataState[recordActive.value];
          dataSource.value = [];
        if (response.code === 0) {
          pagination.total = response.data.length;
          //clear array and then push new record
          dataSource.splice(0);
          dataSource.push(...response.data.records);
        } else {
          $q.notify({
            color: "negative",
            position: "top",
            message: response.message,
            icon: "report_problem"
          });
        }
      }).catch((error) => {
        $q.notify({
          color: "negative",
          position: "top",
          message: error.message,
          icon: "report_problem"
        });
        // console.log("error", error);
      }).then(() => {
        loading.value = false;
      });
    };

    const recordPage = (pagination) => {
      searchForm[recordActive.value].current = pagination.current;
      searchRecord();
    };

    const chgDate = (val) => {
      var gapDate = new Date().getTime() - val * 24 * 60 * 60 * 1000;
      var oldDate = new Date(gapDate);
      var newDate = {
        Y: oldDate.getFullYear() + "-",
        M: (oldDate.getMonth() + 1) < 10 ? "0" + (oldDate.getMonth() + 1 + "-") : (oldDate.getMonth() + 1 + "-"),
        D: (oldDate.getDate()) < 10 ? "0" + (oldDate.getDate() + "") : (oldDate.getDate() + "")
      };
      var useDate = newDate.Y + newDate.M + newDate.D;
      return useDate;
    };

    const getTime = () => {
      ["deposit", "rebates", "transfer", "turnover", "withdraw"].forEach(function(v) {
        if (v in searchForm) {
          searchForm[v].startDate = chgDate(7);
          searchForm[v].endDate = chgDate(0);
        }
      });
      searchRecord();
    };

    onMounted(() => {
      getTime();
    });

    return {
      recordActive,
      searchForm,
      dataState,
      tableColumns,
      commonColumns,
      searchRecord,
      recordPage,
      loading,
      pagination,
      getTime,
      chgDate,
      noDataLabel: "ไม่มีข้อมูล",
      rowPerPageLabel: "บันทึกต่อหน้า",
      humanDatetime(ts) {
        return moment(ts).format("DD-MM-YYYY HH:mm:ss");
      }
    };
  }
});
</script>

